<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/include/billing.php';hms_start_session();hms_require_role('patient');$ready=hms_billing_ready($con);$rows=$ready?hms_db_query($con,'SELECT id,invoice_number,issue_date,total_amount,amount_paid,balance_amount,status FROM billing_invoices WHERE patient_user_id=? ORDER BY id DESC',[(int)$_SESSION['id']]):null;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My billing · MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/themes/theme-1.css"><link rel="stylesheet" href="assets/css/medtech-app.css"></head><body><div id="app"><?php include 'include/sidebar.php';?><div class="app-content"><?php include 'include/header.php';?><main class="main-content"><div class="wrap-content container"><section id="page-title"><h1 class="mainTitle">My billing</h1><p class="text-muted">View invoices, payments, and outstanding balances.</p></section><section class="medtech-report-panel"><?php if(!$ready):?><div class="alert alert-warning"><?=hms_h(hms_billing_notice())?></div><?php elseif($rows->num_rows):?><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><a href="invoice.php?id=<?=hms_h($r['id'])?>"><?=hms_h($r['invoice_number'])?></a></td><td><?=hms_h($r['issue_date'])?></td><td>₹<?=number_format((float)$r['total_amount'],2)?></td><td>₹<?=number_format((float)$r['amount_paid'],2)?></td><td>₹<?=number_format((float)$r['balance_amount'],2)?></td><td><span class="mt-status <?=hms_h($r['status'])?>"><?=hms_h(ucfirst(str_replace('_',' ',$r['status'])) )?></span></td></tr><?php endwhile;?></tbody></table></div><?php else:?><div class="medtech-empty-state"><strong>No invoices yet</strong><span>Invoices issued by the hospital will appear here.</span></div><?php endif;?></section></div></main><?php include 'include/footer.php';?></div></div></body></html>
